import type { Token } from 'antlr4ng';
import { useMemo } from 'react';
import { useMainContext } from '@/context/MainContext';
import { getTokenColor, segment } from '@/lib/token-utils';

/** Renders source with syntax colours. Tabs show a faint arrow so kids can see them. */
export default function Highlighted({ source, tokens }: { source: string; tokens: Token[] }) {
  const { theme } = useMainContext();
  const segments = useMemo(() => segment(source, tokens), [source, tokens]);
  return (
    <>
      {segments.map((s, i) =>
        s.category === 'tab' ? (
          <span key={i} className="tab-mark" style={{ color: getTokenColor('tab', theme) }}>
            {s.text}
          </span>
        ) : (
          <span
            key={i}
            style={{ color: getTokenColor(s.category, theme) }}
            className={s.category === 'comment' ? 'italic' : undefined}
          >
            {s.text}
          </span>
        ),
      )}
    </>
  );
}
/** End Code Generated by Claude on 2026-11-25 */
